import{_ as e,o as a,c as s,a4 as n}from"./chunks/framework.BMj-uaUw.js";const h=JSON.parse('{"title":"单元 7 · AI 协作：组件该不该拆，判断得自己下","description":"","frontmatter":{},"headers":[{"level":2,"title":"这一章哪些活能交给 AI","slug":"这一章哪些活能交给-ai","link":"#这一章哪些活能交给-ai","children":[]},{"level":2,"title":"提示词怎么写","slug":"提示词怎么写","link":"#提示词怎么写","children":[{"level":3,"title":"1. 让它给拆分的候选方案，要求给正反两方理由","slug":"_1-让它给拆分的候选方案-要求给正反两方理由","link":"#_1-让它给拆分的候选方案-要求给正反两方理由","children":[]},{"level":3,"title":"2. 让它核查 props 与 emits 的声明完整性","slug":"_2-让它核查-props-与-emits-的声明完整性","link":"#_2-让它核查-props-与-emits-的声明完整性","children":[]},{"level":3,"title":"3. 让它审一段父子通信有没有违反单向数据流","slug":"_3-让它审一段父子通信有没有违反单向数据流","link":"#_3-让它审一段父子通信有没有违反单向数据流","children":[]}]},{"level":2,"title":"AI 在这一章容易错什么","slug":"ai-在这一章容易错什么","link":"#ai-在这一章容易错什么","children":[{"level":3,"title":"子组件直接改 props","slug":"子组件直接改-props","link":"#子组件直接改-props","children":[]},{"level":3,"title":"拆得太碎","slug":"拆得太碎","link":"#拆得太碎","children":[]},{"level":3,"title":"props 声明不完整","slug":"props-声明不完整","link":"#props-声明不完整","children":[]},{"level":3,"title":"事件名两处对不上","slug":"事件名两处对不上","link":"#事件名两处对不上","children":[]}]},{"level":2,"title":"怎么验收 AI 的产出","slug":"怎么验收-ai-的产出","link":"#怎么验收-ai-的产出","children":[]},{"level":2,"title":"练习","slug":"练习","link":"#练习","children":[{"level":3,"title":"拿一个超过 200 行的组件，让 AI 给拆分方案，然后你至少否掉一条","slug":"拿一个超过-200-行的组件-让-ai-给拆分方案-然后你至少否掉一条","link":"#拿一个超过-200-行的组件-让-ai-给拆分方案-然后你至少否掉一条","children":[]}]}],"relativePath":"unit07/ai-collaboration.md","filePath":"unit07/ai-collaboration.md","lastUpdated":1789356894000}'),o={name:"unit07/ai-collaboration.md"};function d(p,t,r,l,i,c){return a(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="单元-7-·-ai-协作-组件该不该拆-判断得自己下" tabindex="-1">单元 7 · AI 协作：组件该不该拆，判断得自己下 <a class="header-anchor" href="#单元-7-·-ai-协作-组件该不该拆-判断得自己下" aria-label="Permalink to &quot;单元 7 · AI 协作：组件该不该拆，判断得自己下&quot;">​</a></h1><p>这一章讲的是组件之间的边界：什么该拆成组件、父子之间怎么传数据、事件怎么发。</p><p>AI 在这一章有两个固定的偏好。一个偏向多拆 —— 它有“单一职责”这个现成的理由，很容易把组件切得很碎。另一个是忽略声明 —— <code>props</code> 少写一个字段、<code>emits</code> 干脆不声明，代码照跑，只是属性悄悄落到了根元素上、事件悄悄发出去了没人接。</p><p>两件事都不报错，都不影响页面看起来的样子。所以这一节的验收重点不是“代码能不能跑”，而是<strong>声明写全了没、边界是你定的还是它定的。</strong></p><h2 id="这一章哪些活能交给-ai" tabindex="-1">这一章哪些活能交给 AI <a class="header-anchor" href="#这一章哪些活能交给-ai" aria-label="Permalink to &quot;这一章哪些活能交给 AI&quot;">​</a></h2><p>判断标准：<strong>改写和核查可以交，拆分本身不能交 —— 它给的是选项，不是答案。</strong></p><table tabindex="0"><thead><tr><th>任务</th><th>能交给 AI 吗</th><th>为什么</th></tr></thead><tbody><tr><td>给出一份拆分的候选方案</td><td>可以</td><td>当选项看，但决定要你下</td></tr><tr><td>检查 <code>props</code> 声明是否完整</td><td>可以</td><td>漏声明这件事它有固定的核对办法</td></tr><tr><td>检查 <code>emits</code> 有没有声明、命名统一不统一</td><td>可以</td><td>这是机械核对</td></tr><tr><td>把一段 props 改成 <code>v-model</code></td><td>可以</td><td>改写本身是机械工作</td></tr><tr><td>生成递归组件的骨架</td><td>可以</td><td>递归的写法有固定形式</td></tr><tr><td>解释单向数据流为什么不能改 props</td><td>可以</td><td>讲到能判断对错就够</td></tr><tr><td>判断“这个组件该不该拆”</td><td><strong>不能直接信</strong></td><td>它几乎总偏向拆，理由是“单一职责”</td></tr><tr><td>决定组件的命名与放置目录</td><td><strong>不行</strong></td><td>取决于项目的约定，它不知道</td></tr><tr><td>决定 <code>props</code> 的默认值取什么</td><td><strong>不行</strong></td><td>取决于业务，猜出来的默认值比没有更危险</td></tr></tbody></table><p>中间那行是这一章最需要你有主见的地方。<strong>拆分没有唯一正确的答案</strong>，它给的理由（可复用、职责单一、文件太长）通常是对的，但“对不对”和“该不该”是两件事。文件从 400 行拆成 12 个 30 行的组件，可读性是变好还是变差，取决于你的项目怎么用。</p><h2 id="提示词怎么写" tabindex="-1">提示词怎么写 <a class="header-anchor" href="#提示词怎么写" aria-label="Permalink to &quot;提示词怎么写&quot;">​</a></h2><h3 id="_1-让它给拆分的候选方案-要求给正反两方理由" tabindex="-1">1. 让它给拆分的候选方案，要求给正反两方理由 <a class="header-anchor" href="#_1-让它给拆分的候选方案-要求给正反两方理由" aria-label="Permalink to &quot;1. 让它给拆分的候选方案，要求给正反两方理由&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这是一个 400 行的组件：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[粘贴完整代码]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>我想拆，但不确定拆到什么程度。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请给我两个方案：</span></span>
<span class="line"><span>- 方案 A：拆得保守，只拆掉最明显的两处</span></span>
<span class="line"><span>- 方案 B：拆得彻底，按职责拆成多个组件</span></span>
<span class="line"><span></span></span>
<span class="line"><span>每个方案都要写：</span></span>
<span class="line"><span>1. 拆成哪几个组件，各自负责什么</span></span>
<span class="line"><span>2. 拆完之后，哪些数据要从父级传下去，传几个 prop</span></span>
<span class="line"><span>3. 每个方案的一个代价（多传了几层？多写了几个文件？多了一次状态提升？）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>最后给一句你的倾向，并说明在什么情况下你会选另一个。</span></span></code></pre></div><p><strong>为什么这么写</strong>：要两个方案而不是一个，是因为它给单一方案时必然给“拆”的那个，而且只讲好处。逼它同时给出代价 —— <strong>拆的代价通常是“数据要往上提一层”</strong>，这一条在只看单个组件的时候想不到，写出来你才好比较。</p><p>最后那句“在什么情况下你会选另一个”，是把它的倾向性暴露出来。它很可能会说“如果这个组件只在一处用，我选 A”—— 这句话本身就回答了你的问题。</p><h3 id="_2-让它核查-props-与-emits-的声明完整性" tabindex="-1">2. 让它核查 <code>props</code> 与 <code>emits</code> 的声明完整性 <a class="header-anchor" href="#_2-让它核查-props-与-emits-的声明完整性" aria-label="Permalink to &quot;2. 让它核查 \`props\` 与 \`emits\` 的声明完整性&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这是我的子组件：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[粘贴 script setup 部分]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请做两份核查表：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>表一：props</span></span>
<span class="line"><span>| 模板或脚本里用到的属性 | 有没有在 defineProps 里声明 | 声明里的类型对不对 |</span></span>
<span class="line"><span>（把代码里所有从父级来的属性都列出来，包括没声明的）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>表二：emits</span></span>
<span class="line"><span>| 脚本里 emit 了什么事件名 | 有没有在 defineEmits 里声明 | 模板里监听时用的是哪个名字 |</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：不要改代码，只给表。没有问题的行也要列出来。</span></span></code></pre></div><p><strong>为什么这么写</strong>：漏声明这件事只有“全列出来 + 逐个对照”才能发现，靠通读代码很难 —— 因为它不报错。要求“没有问题的行也要列出来”，是为了防止它只报问题、让你误以为没列出来的就是没问题。</p><p>表二的第三列是关键。<strong>事件名在脚本里是 camelCase、在模板里要写成 kebab-case</strong>，这两处对不上时事件就静默失效了。让它把两处名字并排写出来，对不上立刻看得见。</p><h3 id="_3-让它审一段父子通信有没有违反单向数据流" tabindex="-1">3. 让它审一段父子通信有没有违反单向数据流 <a class="header-anchor" href="#_3-让它审一段父子通信有没有违反单向数据流" aria-label="Permalink to &quot;3. 让它审一段父子通信有没有违反单向数据流&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这是父组件和子组件的相关代码：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>父组件：[粘贴]</span></span>
<span class="line"><span>子组件：[粘贴]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请回答：</span></span>
<span class="line"><span>1. 子组件有没有直接修改父级传下来的数据？如果有，在哪一行</span></span>
<span class="line"><span>2. 如果有，改写成“子组件 emit、父组件改”的写法</span></span>
<span class="line"><span>3. 如果子组件改的是 props 里的对象内部的字段（不是整体赋值），</span></span>
<span class="line"><span>   单独说明 —— 这种情况更隐蔽</span></span>
<span class="line"><span>4. 改完之后，父子之间传的东西有没有变多？值不值得</span></span></code></pre></div><p><strong>为什么这么写</strong>：第 3 点是这段提示词里最有用的一句。直接写 <code>props.title = &#39;x&#39;</code> 会报警告，但写 <code>props.item.checked = true</code> 不会 —— <strong>改的是对象里面的字段，Vue 拦不住。</strong> 这类“隐蔽的越权修改”只能靠人看出来，而它平时不会主动查。你点明让它在检查范围里，它才会认真看。</p><h2 id="ai-在这一章容易错什么" tabindex="-1">AI 在这一章容易错什么 <a class="header-anchor" href="#ai-在这一章容易错什么" aria-label="Permalink to &quot;AI 在这一章容易错什么&quot;">​</a></h2><h3 id="子组件直接改-props" tabindex="-1">子组件直接改 props <a class="header-anchor" href="#子组件直接改-props" aria-label="Permalink to &quot;子组件直接改 props&quot;">​</a></h3><p><strong>现象</strong>：子组件里出现 <code>props.item.checked = true</code>、<code>props.list.push(x)</code>、<code>props.title = &#39;新标题&#39;</code>。前两种通常不报警告，页面还正常工作。</p><p><strong>原因</strong>：这是最省事的写法 —— 拿到数据直接改，不用往上传事件、也不用等父组件更新。它写起来顺手，就跑得快。</p><p><strong>怎么处理</strong>：记住为什么不能这么写 —— <strong>父组件的数据可能被多个子组件共享，一个子组件改了，另一个子组件的界面会跟着变，但那个组件的代码里什么都没写。</strong> 出了问题你会去查那个“没动过代码”的组件，方向完全错了。</p><p>改法是固定的三步：</p><table tabindex="0"><thead><tr><th>步骤</th><th>子组件</th><th>父组件</th></tr></thead><tbody><tr><td>1</td><td><code>defineEmits</code> 里声明一个事件</td><td>——</td></tr><tr><td>2</td><td>需要改的时候 <code>emit(&#39;update&#39;, 新值)</code></td><td>监听这个事件</td></tr><tr><td>3</td><td>不直接改 props</td><td>在事件处理函数里改自己的数据</td></tr></tbody></table><p>如果改的只是一个“开关”性质的字段，用组件上的 <code>v-model</code> 更省事 —— <a href="/frontend-engineering-course/unit07/04-vmodel.html">7.4</a>讲的就是它，本质上是“一个属性 + 一个事件”的约定。Vue 3.4 之后还有一个更简洁的写法 <code>defineModel</code>，能用它就少写一半代码。</p><h3 id="拆得太碎" tabindex="-1">拆得太碎 <a class="header-anchor" href="#拆得太碎" aria-label="Permalink to &quot;拆得太碎&quot;">​</a></h3><p><strong>现象</strong>：它把一个列表页拆成了 <code>ListHeader</code>、<code>ListToolbar</code>、<code>ListTable</code>、<code>ListPagination</code>、<code>ListEmpty</code>、<code>ListItem</code>、<code>ListStatusTag</code>。每个文件都只有二三十行。</p><p><strong>原因</strong>：“单一职责”“可复用”是它给拆分理由时的默认词。它不会考虑“这个组件一辈子只在这一处用”这件事。</p><p><strong>怎么处理</strong>：判断一个拆分值不值，问三个问题：</p><ol><li><strong>这个组件会被用到第二处吗？</strong> 不会，而且它只是把一段模板搬走，那就不值。</li><li><strong>拆完之后，有多少数据要往上提一层？</strong> 要是为了拆一个小组件得让父级多管两个状态，代价比收益大。</li><li><strong>看代码的时候，需要来回跳文件吗？</strong> 这是最实用的判断 —— 读一个列表页要开七个文件，那就不如不拆。</li></ol><p><a href="/frontend-engineering-course/unit07/01-sfc.html">7.1</a>里给了“三个信号与两个反信号”，那个比任何通用原则都实用。<strong>信号出现了才拆，反信号出现了就忍住别拆。</strong> 这份清单可以抄进 AGENTS.md 的代码风格一节，让 AI 每次按它来判断。</p><h3 id="props-声明不完整" tabindex="-1"><code>props</code> 声明不完整 <a class="header-anchor" href="#props-声明不完整" aria-label="Permalink to &quot;\`props\` 声明不完整&quot;">​</a></h3><p><strong>现象</strong>：模板里用了 <code>props.type</code>，但 <code>defineProps</code> 里只声明了 <code>item</code> 和 <code>index</code>。少声明一个。</p><p><strong>原因</strong>：它按模板里最明显的用法声明，容易漏掉在 <code>computed</code> 或事件处理函数里用到的那些。</p><p><strong>怎么处理</strong>：漏声明的后果不是报错，而是<strong>这个属性被当成普通的 HTML 属性传下去，落到组件的根元素上</strong>。你在模板上写 <code>type=&quot;text&quot;</code>，结果它跑到了 <code>&lt;div&gt;</code> 上，变成一个无效的 HTML 属性 —— 页面上看不出来，但控制台会有提示，或者在某些浏览器里表现异常。</p><p>核查办法就用上面那个提示词模板，让它把“代码里用到的”和“声明里有的”并排列出来。顺带补一个习惯：<strong>给会从父级传下来的每个 prop 都写上 <code>required</code> 或 <code>default</code></strong>，这样别人读组件时不用猜。</p><h3 id="事件名两处对不上" tabindex="-1">事件名两处对不上 <a class="header-anchor" href="#事件名两处对不上" aria-label="Permalink to &quot;事件名两处对不上&quot;">​</a></h3><p><strong>现象</strong>：子组件里 <code>emit(&#39;updateStatus&#39;, value)</code>，父组件模板里写 <code>@update-status=&quot;...&quot;</code> —— 这一对是对的。但有时它写成 <code>@updateStatus=&quot;...&quot;</code>，然后事件就静默失效了。</p><p><strong>原因</strong>：Vue 的规则是“脚本里用 camelCase 声明和触发，模板里用 kebab-case 监听”，<code>updateStatus</code> 和 <code>update-status</code> 会被自动对应上。但如果两边都用 camelCase 写进模板（<code>@updateStatus</code>），在某些写法下对不上，而且<strong>不报错</strong>。</p><p><strong>怎么处理</strong>：统一成一句话 —— <strong>脚本里 camelCase，模板里 kebab-case，<code>defineEmits</code> 里和 <code>emit()</code> 里必须一致。</strong></p><table tabindex="0"><thead><tr><th>位置</th><th>写法</th></tr></thead><tbody><tr><td><code>defineEmits([&#39;updateStatus&#39;])</code></td><td>camelCase</td></tr><tr><td><code>emit(&#39;updateStatus&#39;, v)</code></td><td>camelCase，和上面完全一致</td></tr><tr><td>父组件 <code>&lt;Child @update-status=&quot;...&quot; /&gt;</code></td><td>kebab-case</td></tr></tbody></table><p>一旦事件没反应，<strong>排查顺序是：先看 <code>emit()</code> 里的名字和 <code>defineEmits</code> 里是否一模一样，再看父组件模板里有没有监听。</strong> 这两个环节里，第一个更容易出问题，因为它不会给任何提示。</p><details class="details custom-block"><summary>还有一类错误：把它自己习惯的命名带进来</summary><p><strong>现象</strong>：它写的 props 叫 <code>listData</code>、<code>itemInfo</code>、<code>dataList</code>、<code>tableData</code>；它写的事件叫 <code>onChange</code>、<code>handleClick</code>、<code>submitForm</code>。</p><p><strong>原因</strong>：这些名字在各类示例代码里出现频率很高，它顺手就用。它不知道你们项目的命名约定是什么。</p><p><strong>怎么处理</strong>：<strong>把命名规则写进 AGENTS.md。</strong> 这一条属于“写一次就永久生效”的约定，不必每次重复交代。</p><p>本项目“校园活动服务平台”的约定是：</p><table tabindex="0"><thead><tr><th>类型</th><th>规则</th><th>例</th></tr></thead><tbody><tr><td>组件文件名</td><td>大驼峰</td><td><code>ActivityCard.vue</code></td></tr><tr><td>组件在模板里的标签</td><td>kebab-case 或大驼峰都可，项目内统一</td><td><code>&lt;ActivityCard /&gt;</code></td></tr><tr><td><code>props</code> 名</td><td>驼峰，不要带 <code>data</code>、<code>list</code> 这类后缀</td><td><code>activity</code>、<code>rows</code>、<code>columns</code></td></tr><tr><td>事件名</td><td>驼峰，动词开头，不要 <code>on</code> 前缀</td><td><code>updateStatus</code>、<code>remove</code></td></tr><tr><td>变量与函数</td><td>驼峰</td><td><code>approvedCount</code></td></tr><tr><td>其他文件名</td><td>kebab-case</td><td><code>activity-rules.js</code></td></tr></tbody></table><p>改这类命名时注意：<strong>它会连模板里的引用一起改</strong>，改完你要在编辑器里搜一遍旧名字，确认没有漏掉的字符串引用（比如动态组件名、<code>component :is</code> 里写的字符串）。</p></details><h2 id="怎么验收-ai-的产出" tabindex="-1">怎么验收 AI 的产出 <a class="header-anchor" href="#怎么验收-ai-的产出" aria-label="Permalink to &quot;怎么验收 AI 的产出&quot;">​</a></h2><p>这一章的产出是组件代码。验收动作的核心是<strong>声明完整性</strong>，因为漏声明不报错。</p><ul><li>[ ] 子组件没有直接修改 <code>props</code>，包括没有改 <code>props</code> 里对象的内部字段</li><li>[ ] 每个从父级传下来的属性都在 <code>defineProps</code> 里声明了，类型也对</li><li>[ ] 每个 prop 都有 <code>required</code> 或 <code>default</code>，别人读的时候不用猜</li><li>[ ] 每个 <code>emit()</code> 的事件都在 <code>defineEmits</code> 里声明了</li><li>[ ] <code>emit()</code> 里的名字和 <code>defineEmits</code> 里完全一致，父组件模板里用的是 kebab-case</li><li>[ ] 拆分的方案是你自己认可的 —— 能说出为什么不拆更多、也不少拆</li><li>[ ] 命名与项目的约定一致，改过名字的地方你搜过了</li><li>[ ] 控制台没有“Extraneous non-props attributes”之类的提示</li></ul><p>最后一条是这个单元的验收里最省事的一条。<strong>“属性落到了根元素上”这类问题，控制台会提示。</strong> 每写完一个组件，开着控制台点一遍，比读五遍代码快。</p><h2 id="练习" tabindex="-1">练习 <a class="header-anchor" href="#练习" aria-label="Permalink to &quot;练习&quot;">​</a></h2><h3 id="拿一个超过-200-行的组件-让-ai-给拆分方案-然后你至少否掉一条" tabindex="-1">拿一个超过 200 行的组件，让 AI 给拆分方案，然后你至少否掉一条 <a class="header-anchor" href="#拿一个超过-200-行的组件-让-ai-给拆分方案-然后你至少否掉一条" aria-label="Permalink to &quot;拿一个超过 200 行的组件，让 AI 给拆分方案，然后你至少否掉一条&quot;">​</a></h3><p><strong>任务</strong>：从你的项目或本周的案例（<a href="/frontend-engineering-course/unit07/05-case-tree.html">案例 03 树状视图</a>、<a href="/frontend-engineering-course/unit07/06-case-editable-table.html">案例 09 可编辑表格</a>都是好素材）里挑一个超过 200 行的组件，让 AI 给拆分方案，然后<strong>至少否掉其中一条</strong>，并写清否掉的理由。</p><p><strong>要求</strong>：记录里必须包含这四项：</p><table tabindex="0"><thead><tr><th>项</th><th>要求</th></tr></thead><tbody><tr><td>原组件的行数与结构</td><td>标出它有哪几块，各占多少行</td></tr><tr><td>AI 的拆分方案</td><td>拆成哪几个，每个负责什么，附它给的理由</td></tr><tr><td>你否掉的那一条</td><td>写清否掉哪个、依据是什么</td></tr><tr><td>你最终采纳的边界</td><td>拆成了什么，说清判断依据</td></tr></tbody></table><details class="details custom-block"><summary>验收标准与参考思路</summary><p><strong>为什么要“至少否掉一条”</strong>：这是这一节练习的核心设计。如果你一条都否不掉，说明你只是把判断权交给了它 —— 而“组件该不该拆”正是这一章要你自己下的判断。否掉一条不需要它错得离谱，只要“我认为不值得”，并且你说得出理由。</p><p><strong>思路提示</strong>：</p><ul><li>否掉的理由可以从这三个里挑：<strong>这个组件只会用在这一处</strong>（复用性不成立）、<strong>拆完之后父级要多管两个状态</strong>（代价大于收益）、<strong>读代码要来回跳文件</strong>（可读性变差）。</li><li>对照<a href="/frontend-engineering-course/unit07/01-sfc.html">7.1</a>里的“三个信号与两个反信号”。如果它拆出来的组件一个信号都不符合，那这条就该否。</li><li>它给的理由里如果出现“符合单一职责原则”“便于后续扩展”，追问一句：<strong>“这个组件在多远的将来会被扩展？具体扩展什么？”</strong> 答不上来的，就是空理由。</li><li>采纳与否掉都要写依据。<strong>这份记录的价值在于依据，不在于结论。</strong></li></ul><p><strong>不合格的写法</strong>：</p><blockquote><p>AI 把组件拆成了 6 个，看起来挺合理的，我就照做了。</p></blockquote><p>“看起来合理”不是依据。它拆出来的每个组件，你能说清为什么是这几个、而不是 4 个或 8 个吗？</p><p><strong>合格的写法</strong>：</p><blockquote><p>原组件 340 行，分三块：表格本体约 150 行、单元格编辑逻辑约 120 行、工具栏约 40 行。 AI 拆成 6 个：EditableTable、EditableCell、TableToolbar、TablePagination、 TableStatusTag、TableEmpty。 我否掉了 TableStatusTag —— 它只有 12 行，就是一个 <code>&lt;span&gt;</code> 加三层条件判断， 而且只在这个表格里用。拆出去之后，表格组件还得把这个标签组件的名称引进来， 读代码时多跳一个文件。 TableEmpty 我也否了，理由同上：四态里的空状态在这个项目里已经有统一写法， 单独拆一个组件反而破坏了四态模板的完整性。 最终采纳 4 个：EditableTable、EditableCell、TableToolbar、TablePagination。 依据是 7.1 里的三个信号 —— 这四个都符合“有独立状态”“会被复用”“模板超过 80 行” 其中之一，被否掉的两个都不符合。</p></blockquote><p>差别在于：后者每条结论后面都有可检验的依据，而且依据来自课程里明确给出的判断标准，不是感觉。</p></details><hr><p>上一节：<a href="/frontend-engineering-course/unit07/06-case-editable-table.html">案例 09 · 可编辑表格</a> · 课后练习：<a href="/frontend-engineering-course/unit07/practice.html">单元 7 课后练习</a></p>`,58)])])}const u=e(o,[["render",d]]);export{h as __pageData,u as default};
